quests[56097] = { id = 56097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grime-Coated Disc", description = "<Look for someone that can help recover the data trapped on this grime-coated disc.>" }
quests[56098] = { id = 56098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defensive in Death", description = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Instructor Ulooaka will have more insight on how to keep this herb from defending itself.>", completion = "Zin'anthids are no mere plant, {name}. They are living beings and as such, know when a predator is trying to harvest them. And yes, even in death they defend themselves.\nIf you wish to harvest all they have to offer, you must lure them into a false sense of security. Here, let me show you a technique I know.", objectives = "Ask Instructor Ulooaka about the tentacles of the Zin'anthid.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56099] = { id = 56099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Font of Corruption" }
quests[56103] = { id = 56103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ounces of Osmenite", description = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Instructor Ulooaka knows of still a better way to mine this ore.>", completion = "Ah yes, that's due to the fragile nature of the ore. You need to adjust your style a bit.\n\nInstead of heavy, powerful swings, try picking away at the edge of where the ore meets the rock.\n\nLike peeling the skin off a fruit. Here, let me show you what I mean...", objectives = "Ask Instructor Ulooaka about the Osmenite Shards.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56104] = { id = 56104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[56107] = { id = 56107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of the Hive" }
quests[56108] = { id = 56108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaving the Hive", description = "<The enormous bee twitches its antennae toward you. It swings its abdomen toward the cave exit.>\n\nBarry might know what's going on.", completion = "<It wriggles eagerly in its new harness.>\n\nBzzz!", objectives = "Speak to Barry in the Honeyback Hatchery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56109] = { id = 56109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender of the Hive" }
