quests[56113] = { id = 56113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest", sourceObjective = "Acquire 1 Rich Jelly and return it to the Hivemother.", sourceObjectiveStatus = "unverified-source-field" }
quests[56116] = { id = 56116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even More Recycling", progress = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", completion = "You deposit the bundle of parts into the Recyclerizer DX-82.  The doors close and the machine surges to life, a slight buzzing sound begins emanating from within. The sound increases in frequency, the slight buzz giving way to a high-pitched whirring. The machine shakes violently, seemingly ready to explode..." }
quests[56117] = { id = 56117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recyclable Parts", description = "<This bundle of recycling could be valuable. The gnomes in the area appear to be dropping their scrap into some nearby contraptions.>", progress = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", completion = "You deposit the bundle of parts into the Recyclerizer DX-82.  The doors close and the machine surges to life, a slight buzzing sound begins emanating from within. The sound increases in frequency, the slight buzz giving way to a high-pitched whirring. The machine shakes violently, seemingly ready to explode...", objectives = "Collect 1 Bundle of Recyclable Parts", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56118] = { id = 56118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snap Back", description = "I have a favor to ask of you, if you would be so kind.\n\nScrollsage Nola gave me this scroll to protect me on my adventures here in Nazjatar. She is a kind soul, but her scroll-work isn't always the most...accurate.\n\nYou look like a brave adventurer who's seen a thing or two. Could you test out the scroll for me? While you're there you may as well cull their numbers a tad.", completion = "Wow! That powerful huh? \n\nI will be sure to keep this with me then!", objectives = "Use the Scroll of Busting Power on Snapdragon Terrormaws and slay snapdragons in Nar'anan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56119] = { id = 56119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waveblade Ankoan", description = "Assist the Ankoan in Nazjatar by completing 4 world quests.", progress = "Return to me when you have finished aiding the Ankoan, {name}.", completion = "May Neptulon shower you with his blessings, friend.", objectives = "Complete any 4 world quests in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56120] = { id = 56120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unshackled", description = "Assist the Unshackled in Nazjatar by completing 4 world quests.", progress = "Return to me when you have finished aiding us, {name}.", completion = "You've really made a difference out there! \n\nThank you, friend.", objectives = "Complete any 4 world quests in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56121] = { id = 56121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jumping Jellies" }
quests[56126] = { id = 56126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seams to be a Problem", description = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with.\n\nIt may be worth talking to Instructor Ulooaka to see if there's a way to prevent this loss from happening.>", completion = "The seams that osmenite flows through are structurally different than that of their mere deposits.\n\nIf you want to harvest the full amount of osmenite from a seam, you'll have to ignore the ore all together and go for the rock surrounding it.\n\nIt's a bit counter to how you normally mine, but trust me, you'll be pleasantly surprised with the results.", objectives = "Ask Instructor Ulooaka about the Osmenite Dust.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56128] = { id = 56128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drowning the Horde", description = "We must strike now before the Horde have a chance to gain a secure foothold. Attack their champions and knock them on their heels.", completion = "If we keep up the pressure there is no way the Horde will succeed.", objectives = "Kill 25 Horde players in Nazjatar while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56129] = { id = 56129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Battle for Stromgarde" }
quests[56131] = { id = 56131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security First", description = "Many dangerous creatures and allies of my father still seek to destroy us.\n\nHelp secure this island, seek out and and eliminate five of our most powerful enemies.", objectives = "Defeat Rare enemies on the island of Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56136] = { id = 56136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Warfront: The Battle for Stromgarde", description = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall!\n\nPrepare yourself for battle.", completion = "Well fought, {name}, though I'm afraid it may be premature to let our guard down just yet. I am sure our enemy will not sit idly while we rebuild Stromgarde.", objectives = "Defeat the Horde at the Battle for Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56137] = { id = 56137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Warfront: The Battle for Stromgarde", description = "Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt!\n\nTake up arms. The Alliance is upon us.", completion = "A battle well fought, {name}. You have once again proven yourself a great warrior of the Horde.", objectives = "Defeat the Alliance at the Battle for Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56139] = { id = 56139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junkyard Treasures", description = "Everyone here needs to work hard to find resources for our cause. \n\nLocate and open ten mechanized chests on the island." }
quests[56141] = { id = 56141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security First", description = "Many dangerous creatures and allies of my father still seek to destroy us.\n\nHelp secure this island, seek out and and eliminate five of our most powerful enemies.", objectives = "Defeat Rare enemies on the island of Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56142] = { id = 56142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adapt, Improve, Overcome!", description = "Izira Gearsworn is still alive, she is Rustbolt's strongest fighter, but her legs are broken. If we're going to survive I need parts to repair and upgrade her.\n\nThere are machines all over with parts we can salvage. With some perseverance we should be able to fix Izira's legs.\n\nHelp me obtain the following parts.", progress = "We need to start searching!", completion = "These are in excellent shape!", objectives = "20 Pristine Hound Bolts, 4 Steel Tibia XS, and 2 Machined Heel Nut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56143] = { id = 56143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Professor Elryna", description = "From the looks of it, Elryna's story should have a very interesting end. This pylon here has been acting up, but I think I know why!\n\nThese things use memory cores, little crystals found within the center of the orb. I bet there's one in that old magi tower. \n\nThere's a snapdragon that's bigger than the terrormaws in there so here, keep the scroll for now. It should help in your fight. She's a big one!", progress = "What happened that fateful day?", completion = "So. She was betrayed by that general?\n\nHe probably proceeded to take all the credit himself. \n\nShame. But at least now we have the knowledge! Thank you, {name}.", objectives = "Defeat the Snapdragon Matriarch, collect the Memory Core, and activate the Memory Pylon to witness the fate of Professor Elryna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56145] = { id = 56145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Advanced Adventurer Augment", description = "<This blueprint details how to condense even more power into a ring or trinket!\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste.", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56146] = { id = 56146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Kelpberry Wine", description = "<This is an empty kelpberry juice cask.\n\nThere is someone nearby that may appreciate a refill.>", progress = "Did you bring me something?", completion = "Oh, you know exactly what this ol' girl likes!", objectives = "Deliver Kelpberry Wine to Maedin in Maedin's Challenge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56148] = { id = 56148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Nazjatar", description = "Our objectives in Nazjatar are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", completion = "Good work, {class}.", objectives = "Slay Alliance within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56149] = { id = 56149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed Them All", description = "I am grateful for the help that your Alliance has given my people, but we are desperately short on food and supplies.\n\nIf we do not gather enough supplies to take care of both the Alliance and my clan, we will run out of food within the week.\n\nThankfully, there appears to be an abundance of fathom rays in the area, but I will need help hunting them in order to gather enough food for our camp.\n\nTake this fathom hook and use it to pull down the fathom rays from above.", progress = "Have you returned from the hunt?", completion = "You have brought back a hefty supply of fathom meat. I will make sure that it gets hauled back to camp. Thank you for your service, {class}.", objectives = "Collect 10 Fathom Flesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56150] = { id = 56150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Kritch", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. \n\n<Rlgmrr jumps around anxiously and points toward the cave.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<He makes a scary face and pinching motions with his hands.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", progress = "Mrgglrmr grm?", completion = "Llrmmrgl! Mrgggl mrgl!\n\n<Rlgmrr laughs.>", objectives = "Kill the Kritch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56151] = { id = 56151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poen's Favorite Dish", description = "Poen is always helping us take care of every rescue we find.\n\nCan you collect some meat from the eels south of here?\n\nI like to make his favorite dish every now and then, to repay him.\n\nIt also has a great effect on the ones recovering. \n\nThe power of deliciousness, I tell you!", progress = "Did you get enough meat?", completion = "This really is a special treat for all of us.\n\nThank you!", objectives = "Collect 15 Fresh Unagi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56152] = { id = 56152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn the Scale", description = "I am in need of your help, {class}. I have been hunting the nearby hydras for their scales, but my weapon was broken in the melee.\n\nThe scales of the hydra make durable and resilient armor for our warriors. Our clan requires the scales to craft and repair our armor.\n\nIf we do not resupply soon, we will be ill-equipped in our fight against the naga.", progress = "Have you completed the hunt?", completion = "Thank you, {class}. These scales will help us greatly in our war against the naga.", objectives = "Collect 20 Hydra Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56153] = { id = 56153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Most Delicious Clams", description = "Neptulian clams are an important part of the ankoan diet.\n\nMany forget how important proper nutrition is during a time of war. A warrior can be armed with the finest weapons and training, but if she is not healthy and well-nourished she will be ineffective in battle.\n\nNow that Mezzamere is home to your Alliance, we must work hard to gather enough food to feed our soldiers.\n\nGather as many Neptulian clams as you can find and I will see that they make it back to camp safely.", progress = "Have you gathered the Neptulian clams?", completion = "These will serve us well.\n\nThank you, {class}.", objectives = "Collect 10 Neptulian Clams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56154] = { id = 56154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where They Hide", description = "The naga are sending assassins to eliminate our forces.\n\nThey hide nearby and murder those they cannot steal away to the slave pens.\n\nTake this special sea sponge with you. The spores will reveal the naga in all their treachery.\n\nOnce revealed, slay the assassins before they can flee for reinforcements.\n\nAzshara will fall!", progress = "Have the naga assassins been eliminated?", completion = "Well done, {class}. The road is now much safer to travel.", objectives = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56155] = { id = 56155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "The geysers are dangerously unstable and will be erupting any moment now.\n\nI fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar.\n\nWe have to do what we can to prevent any further destruction.\n\nTake this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", progress = "Were you able to prevent the geysers from erupting further?", completion = "Good work, {name}. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location.", objectives = "Seal 5 Unstable Geysers and slay the Disturbed Algan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56156] = { id = 56156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tempered Blade", description = "These blades that I wield are newly forged. The time has come to temper them in the blood of my enemies.\n\nI have heard that you are skilled in the ways of battle. I too am proficient in the business of death and I would be honored to fight at your side.\n\nAccompany me, {class}, and together we will spill the blood of our enemies.", progress = "A blade is not worthy of a warrior until it is tempered in the blood of the enemy.", completion = "It was an honor to fight by your side, {name}. If you should have need of me in the future, you need only ask.", objectives = "Slay 15 naga with Bladesman Inowari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56157] = { id = 56157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "There are several geysers nearby that will be erupting soon.\n\nUnfortunately, the elements in this area are not stable enough to handle the force of the eruptions.\n\nI need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance.", completion = "Good work, {name}. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location.", objectives = "Seal 5 Unstable Geysers and slay the Disturbed Algan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56158] = { id = 56158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "The elements are becoming increasingly unstable due to Azshara's abuse of the Tidestone.\n\nGeysers will be erupting nearby at any moment. Each eruption threatens to destroy the delicate balance of life on the surface.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance and redistribute the explosive underground pressure to a safer location.", completion = "Good work, {name}. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location.", objectives = "Seal 7 Unstable Geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56159] = { id = 56159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "The geysers are dangerously unstable and will be erupting any moment now.\n\nI fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar.\n\nWe have to do what we can to prevent any further destruction.\n\nTake this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", progress = "Were you able to prevent the geysers from erupting further?", completion = "Good work, {name}. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location.", objectives = "Seal 7 Unstable Geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56160] = { id = 56160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "There are several geysers nearby that will be erupting soon.\n\nUnfortunately, the elements in this area are not stable enough to handle the force of the eruptions.\n\nI need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar.\n\nTake this sealant and use it to plug the geysers while I work to restore the elemental balance.", progress = "Have the geysers been sealed?", completion = "Good work, {name}. Thanks to your help sealing the geysers, I've been able to stabilize the elements and redirect the pressure to a safer location.", objectives = "Seal 6 Unstable Geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56161] = { id = 56161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Out to Sea", description = "Now that things're under control here, I'm sure they could use your help back in Nazjatar!\n\nWhy don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", completion = "Welcome back. There's work to do.", objectives = "Return to Newhome in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56162] = { id = 56162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Out to Sea", description = "Now that things're under control here, I'm sure they could use your help back in Nazjatar!\n\nWhy don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", completion = "Thank you for returning to assist us. There's more to be done.", objectives = "Return to Mezzamere in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56163] = { id = 56163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound Elemental" }
quests[56165] = { id = 56165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Extraordinary Adventurer Augment", description = "<This blueprint details how to condense an extraordinary amount of power into a ring or trinket!\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste.", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56166] = { id = 56166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Needs of the People", description = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up.\n\nBe sure to report what you find to Speaker Utia.", objectives = "Speak to people in Mezzamere about things they need.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56167] = { id = 56167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Highlands", description = "When I first sensed these essences, I did not anticipate the importance of the role they would play. It is only a matter of time before all of the dragonflights are brought into the fold.\n\nThough I have reached out to the other Aspects, I have yet to hear from Alexstrasza. It is odd that she would be silent while these powers manifest.\n\nShe was last seen in the Vermillion Redoubt in Twilight Highlands.\n\nI fear she may be in trouble. We must hurry.", completion = "It is far worse than expected. We tried to reach the Redoubt, but did not even make it to the ridge.\n\nSomething is watching the skies and preventing us from reaching Alexstrasza.", objectives = "Meet Kalecgos in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56168] = { id = 56168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Factory Refurbished", description = "I need you to get us a Recycled Crawler Manifold.\n\nYou should be able to get one up at Junkwatt Depot if you recycle parts found there.", progress = "Head up to the Junkwatt Depot and get working!", completion = "Nice work, this is just what I needed.", objectives = "Recycled Crawler Manifold obtained.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56170] = { id = 56170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[56171] = { id = 56171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[56172] = { id = 56172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar.\n\nDeliver them to me and Madam Goya will consider you for special access.", progress = "Have you found these items.", completion = "Excellent work, we shall speak again.", objectives = "Deliver 5 Curious Murloc Horn to Steelsage Gao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56173] = { id = 56173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar. \n\nDeliver them to me and Madam Goya will consider you for special access.", progress = "Have you found these items.", completion = "Excellent work, we shall speak again.", objectives = "Deliver 5 Unidentified Mass to Steelsage Gao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56174] = { id = 56174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep your eyes out for these particular items during your travels in Nazjatar. \n\nDeliver them to me and Madam Goya will consider you for special access.", progress = "Have you found these items.", completion = "Excellent work, we shall speak again.", objectives = "Deliver 5 Disintegrating Sand Sculpture to Steelsage Gao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56175] = { id = 56175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emission Free", description = "We're going to need a few Empty Energy Cells to fill out the battery pack on the mount control assembly. \n\nSee if you can find me these.", progress = "We need to fix this battery pack.", completion = "Nice work, this will help a lot.", objectives = "Collect 20 Empty Energy Cells", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56177] = { id = 56177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Conduit" }
quests[56178] = { id = 56178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Conduit" }
quests[56180] = { id = 56180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound Elemental" }
quests[56181] = { id = 56181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One's on Me", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", completion = "You've done good work around town, {name}. A real asset to the resistance.\n\nI've also seen you admiring my blowtorch... Quite the creation, isn't it?\n\nTell you what, I'll unlock the blueprint for the Scrapmaster Blowtorch on Pascal-K1N6 for you.\n\nNo need to thank me. Excellence should be rewarded." }
quests[56184] = { id = 56184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirates, Sea Monsters, Robots", description = "I finally found it! This is the resting place of my father, after his crew mutinied and left him here to die.\n\nI've scouted the island, and found the locations of three chests that contain mementoes of my father. \n\nDo this for me and my family. Recover my father's sword, clothing, and bones from the three chests I've marked.", progress = "Help my recover the remains of my father.", completion = "I can never thank you enough, so I won't.", objectives = "Recover DeMeza's father's Sword, Clothing and Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56185] = { id = 56185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of N'Zoth", description = "Are you curious how I came to be here, in the Chamber of Heart? \n\nOf course I arrived of my own volition, but there was quite a search for me, for a time.\n\nKalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", completion = "I knew that N'Zoth was powerful, but to reach Ebonhorn within the safety of the Chamber... \n\nWe have to do something about this. None of us are safe.", objectives = "Speak to Kalecgos in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56186] = { id = 56186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spies to the Left and Right", progress = "The Black Prince isn't here. But we might be able to help you find him.", completion = "Good work getting rid of those spies.\n\nThings have been quiet here for a long time. And now, suddenly, all eyes are on us. So to speak.\n\nThe Black Prince is notoriously secretive about his plans. I'm not in the habit of reading other people's journals, but I'm guessing he expected you to feel differently about it.", objectives = "Seek out Wrathion at the Tavern in the Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56187] = { id = 56187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Winged Shadow", description = "Obviously, the Black Prince isn't here. Trust me when I say he's not an easy one to find.\n\nIf I were you, I'd make my way to Blackrock Mountain. There's a terrace carved into its slopes, where Nefarian once made his lair.\n\nWrathion has been monitoring that place for a long time. Even if he's not there himself, you might find someone who knows where to look.\n\nAnd {class}... it's clear you're not the only one searching for him. Watch your back.", progress = "My head is still spinning... they showed me... such terrible... tempting things...", completion = "Thank you. They... forced their way into my mind. I couldn't stop them from finding what they sought.\n\nThe Black Prince meant for you to have those pages. He was certain that you would need the knowledge within them.", objectives = "Seek out Wrathion outside the entrance to Blackwing Descent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56188] = { id = 56188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Catacombs!", description = "I held out as long as I could, but... the whispers were too strong.\n\nYou must hurry to Karazhan. The Black Prince said he intended to study the artifacts stored within its catacombs.\n\nPlease, do not allow my failure to bring about his doom!", progress = "<It seems the lookout gave his life in service to the Black Prince.>", completion = "<The lookout put up a fierce fight before he died.\n\nYou have found more pages from Wrathion's journal on his body. Perhaps the Black Prince himself is not far.>", objectives = "Seek out Wrathion outside the Karazhan Catacombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56189] = { id = 56189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Trail of the Black Prince", description = "<It looks like a fight took place here. N'Zoth's agents must have already entered the catacombs beneath Karazhan.\n\nThe dead lookout still has a set of keys on him. Perhaps they will unlock the door.\n\nWith any luck, you can find Wrathion before N'Zoth's agents and gain something that can help Ebonhorn.>", progress = "<The note appears to have been left behind in a hurry, and deliberately placed where you would find it.>", completion = "The note reads:\n\n\"{name}. If you are reading this note, then I assume that Ebyssian has fallen prey to the whispers of the Old Gods. Fortunately, I have prepared a method to save him.\n\nYou will find a potion with the properties you seek sitting next to this note. Bring it to my brother and it will clear his mind of N'Zoth's influence.\n\nI will thank you for your efforts in person, soon enough.\"", objectives = "Enter the Karazhan Catacombs and search for a cure for Ebonhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56190] = { id = 56190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Ebonhorn", description = "<The potion appears to be powerful and chaotic. It changes color seemingly at random.\n\nThis must be the concoction Wrathion wrote about in his journal. Just standing near it grants you a sense of peace and clarity.\n\nYou may not have found the Black Prince himself, but perhaps what he left behind for you can help Ebonhorn.>", completion = "My mind is finally my own again. Whatever Wrathion brewed into that potion has quieted the whispers.\n\nBut I take it you did not find the Black Prince himself.", objectives = "Return to the Chamber of Heart and treat Ebonhorn with the Potion of Mental Clarity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56205] = { id = 56205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Ptrust Me On This", description = "Ahhh, it is good to see you, {name}.\n\nHow is de defective one? Still pleased to be at your side?\n\nI have given this some thought. Fear may still be what holds your not-so-little one back, but your love is what enables him to thrive without his wings. Perhaps that love will be what restores him to de skies.\n\nI am asking you to trust me. I wish to try something.\n\nIf I am correct then de two of you will find yourselves airborne as nature intended!", completion = "What did I tell you, child?\n\nAll he needed was de right motivation. Haha!", objectives = "Place your faith in Pa'ku and Kua'fon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56206] = { id = 56206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Battle for Stromgarde" }
quests[56209] = { id = 56209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls of Origination", description = "It looks like the Halls of Origination have been claimed by a group o' tol'vir calling themselves the Amathet. I don't know much about them other than they're new in town and not the friendliest of types.\n\nWe'll need tae get in there and re-activate the forge, or else Azeroth will be done for!", progress = "Azeroth's gonna be done for if we dun get this thing back online!", completion = "We got the forge back, but not before N'Zoth was able tae cripple her systems. \n\nI'm afraid our work is far from done.", objectives = "Defeat the Amathet forces and reactivate the forge in the Halls of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56210] = { id = 56210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Stones", description = "I have a gift for you, {name}. \n\nIt's a stone unlike anything you've seen before. To the uninformed, it may seem to be a simple rock, but it's far more precious than that. \n\nThis is a scrying stone. It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. \n\nUse the stone to reveal treasure hidden away by ancient magic.", completion = "See, I wasn't lying. The scrying stones are extraordinary!", objectives = "Find treasures hidden away by magic within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56211] = { id = 56211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Stones", description = "I have a gift for you, {name}. \n\nThis stone is unlike anything you may have seen before. To the uninformed, it appears to be a simple rock, but it is far more precious than that.\n\nThis is a scrying stone. It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. \n\nUse the stone to reveal treasure hidden away by ancient magic.", progress = "Have you found any treasure?", completion = "As you are now aware, these stones are quite extraordinary.", objectives = "Find treasures hidden away by magic within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56214] = { id = 56214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Girl", description = "I have learned so much by your side, I can't believe how many naga we've taken down!\n\nWhen you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope.\n\nBut now, we see a way out of the darkness of the depths, finally!\n \nI took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her.\n\nShe'll make a great mount... and loyal friend.", sourceObjective = "Accept a gift from your companion.", completion = "Take good care of her, ok? She means a lot to me. \n\nShe likes fathom ray eggs best, so remember that.\n\nGoodbye, little one! Neri loves you!", sourceObjectiveStatus = "unverified-source-field" }
quests[56215] = { id = 56215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glittering Shell", description = "Hi, friend. I just wanted you to know that traveling with you has been the best ever!\n\nI never thought I could learn so much about fighting, but now I feel like I can actually hold my own.\n\nI will protect all of the wee ones that can't protect themselves!\n\n<Poen produces a crab from somewhere, it has a bright shell.>\n\nLike this little one. I found him a while back, while we were out. He looked so scared.\n\nHey, why don't you take him?", sourceObjective = "Accept a gift from your companion.", completion = "I've never seen one with a shell this brightly-colored, must make him a target.\n\nWithout you, we could have both been doomed.\n\nHere, take him, it's because of you that we're all a lot safer now.\n\nI have more friends to protect!", sourceObjectiveStatus = "unverified-source-field" }
quests[56216] = { id = 56216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Heirloom", description = "We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat.\n\nI will be honest with you, friend. I did not think I would live this long.\n\nMy people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own.\n\nThis is mine. I have none to pass it on to. I would like you to have it", sourceObjective = "Accept a gift from your companion.", completion = "This charm is one of luck, it was passed down through many years of my people.\n\nIt has brought me little luck, until now, until it brought you to me.\n\nIt is only fitting that you take it from here.", sourceObjectiveStatus = "unverified-source-field" }
quests[56217] = { id = 56217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Tame", description = "In our time together, I have learned much. Both about my own abilities, and about your people. \n\nYou are selfless in the face of challenge, much like our own. I consider us kin.\n\nFor some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter.\n\nHere, he is yours.", sourceObjective = "Accept a gift from your companion.", completion = "Take care when feeding him, the poison is no less lethal to a friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[56218] = { id = 56218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beauty in the Deeps", description = "We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side.\n\nYet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed.\n\nThere is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors.\n\nYou see? There is beauty here, even now.", sourceObjective = "Accept a gift from your companion.", completion = "Take this crab, may it be a symbol of the beauty that once reigned in this place.\n\nWith your help, it will again.", sourceObjectiveStatus = "unverified-source-field" }
quests[56219] = { id = 56219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Tears", description = "We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are.\n\nI have something to show you...\n\n<Vim produces a book from his pack.>\n\nWorst thing we can do is forget.\n\nSo many names I've written in this book, each and every one of them an Unshackled. All of them gone, now.\n\nI will never forget their names.\n\nI want you to have it. Tell people. Tell them who they were, and what we have done here.", sourceObjective = "Accept a gift from your companion.", completion = "This book contains the names of brave creatures of all kinds that helped us, fought for us, and died for us.\n\nHelp me remember them.", sourceObjectiveStatus = "unverified-source-field" }
quests[56222] = { id = 56222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lady Naz'jess", description = "Wanted for attacks against the people of Nazjatar. \n\nLady Naz'jess has been driving the weapon masters to create crueler devices.\n\nLast seen skulking about Zanj'ir Terrace. She is vicious, proceed with caution.\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", progress = "Has her command come to an end?", completion = "Well done, {class}. Lady Naz'jess had become a thorn in the side of the people here.", objectives = "Retrieve the head of Lady Naz'jess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56223] = { id = 56223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Commander Sarj'eth", description = "Wanted for attacks against the people of Nazjatar. \n\nCommander Sarj'eth has attempted to enslave many Horde survivors.\n\nHe commands slavers in Zanj'ir Terrace. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", progress = "Did the brave commander reach the end of his days?", completion = "Sarj'eth was a high-ranking commander among the naga. \n\nThese people will sleep better, knowing he is gone.", objectives = "Retrieve the head of Commander Sarj'eth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56224] = { id = 56224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lord Ha'kass", description = "Wanted for attacks against the people of Nazjatar. \n\nLord Ha'kass has attempted to enslave many Horde survivors.\n\nHe commands slavers in Zanj'ir Wash. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", progress = "Was the villain found?", completion = "Filth like him does not deserve to keep their head.\n\nYou just made the world a little bit better.", objectives = "Retrieve the head of Lord Ha'kass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56225] = { id = 56225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lady Narjiss", description = "Wanted for attacks against the Horde!\n\nLady Narjiss is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen on the outskirts of Zanj'ir Terrace. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", progress = "Did you silence her?", completion = "Lady Narjiss brought with her a darkness. The world feels a little lighter now.", objectives = "Retrieve the head of Lady Narjiss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56226] = { id = 56226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gler'thogg", description = "Gler'thogg is responsible for the death and torture of many of the Unshackled. \n\nThey have shared with us their pain. Bring back his eye.\n\nHe dwells in the Deepcoil Tunnels. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", progress = "Is this your first enucleation?", completion = "That tentacled terror will torture them no more.", objectives = "Retrieve the Eye of Gler'thogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56227] = { id = 56227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Inquisitor Ithriza", description = "Wanted for attacks against the Horde!\n\nInquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen in the vicinity of Dragon's Teeth Basin. Extreme caution advised!\n\nUpon completion of the mission, report to Seacaller Unow for commendation.", progress = "Did you knock him down a peg?", completion = "One tormentor down, so many to go.", objectives = "Retrieve the head of Inquisitor Ithriza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56231] = { id = 56231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforced Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind.\n\nReinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", progress = "The chest is locked and requires a key.", completion = "As you turn the key you can hear the heavy latches of the chest snap open with considerable force...", objectives = "Locate the key to the Naga Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56232] = { id = 56232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", progress = "The chest is locked and requires a key.", completion = "The magical barrier dissipates as you insert the key...", objectives = "Locate the key to the Naga Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56233] = { id = 56233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Cache", description = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga commanders.", progress = "The chest is locked and requires a key.", completion = "The magical barrier dissipates as you insert the key...", objectives = "Locate the key to the Naga Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56234] = { id = 56234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends In Need", description = "I doubt that will be the last we've seen of Priscilla, but at least she is no longer one of our immediate concerns.\n\nWe must think carefully before making our next move. In the meantime we should continue to build upon our relationship with our new allies, the Ankoan. Work with them to secure the area and hone their skills, we're not out of the woods yet.\n\nI fear the biggest battle is still to come. Let's show them that together we can take on Azshara's forces and succeed!", completion = "Good work, while you were gone Shandris and I have been talking and I think she's found a promising lead for us to focus our efforts.", objectives = "Support your allies in Nazjatar by gaining 3000 experience combined between Farseer Ori, Hunter Akana, and Bladesman Inowari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56235] = { id = 56235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Into Nazjatar", description = "We have much to do {name}. However our troops are weary and need rest. Decisions made when tired are often the wrong ones.\n\nThese \"Unshackled\" have offered to aid us with what forces they have. If we hope to survive down here against Azshara's forces, we will need to support our new allies.\n\nJoin one of their hunters and aid them in their tasks, we will remain here and discuss our next move.", completion = "Excellent work. Your efforts have helped us rebuild our supplies and gained our friends some much-needed combat experience.\n\nThey have entrusted us with this item, which appears to be quite magical. I cannot harness the power, but perhaps your Heart of Azeroth can. Take it, may it do us some good in this strange place.", objectives = "Support your allies in Nazjatar by getting one to rank 3.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56236] = { id = 56236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down But Not Out", description = "Ashvane won't trouble us for now, but our situation remains perilous.\n\nI must consider our next move, {name}. In the meantime we should continue to build upon our relationship with our new allies, the Unshackled. Test them in combat, train them while you can, we will need their aid in the battles to come.\n\nWe will show them that through unity there are no obstacles that can stand in our way.", completion = "Good work, while you were gone I was able to make some progress in locating our next objective.", objectives = "Support your allies in Nazjatar by gaining 2400 experience combined between Vim Brineheart, Poen Gillbrack, and Neri Sharpfin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56239] = { id = 56239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Silver Knife", description = "<This silver knife is small and lightly decorated, you found it inside of a chest. \n\nIt was more likely used for eating or preparing food than combat. What would the naga need with such a thing?\n\nOne of the Ankoan may know more...>", completion = "What do you have there?\n\nAh, yes, you found this within one of the chests? We have found similar things inside of them -- finery, decorative platters, and the like. Perhaps they do not belong to the naga? It is a mystery.", objectives = "Ask the Ankoan about the knife.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56240] = { id = 56240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Silver Knife", description = "<This silver knife is small and lightly decorated, you found it inside of a chest. \n\nIt was more likely used for eating or preparing food than combat. What would the naga need with such a thing?\n\nOne of the Unshackled may know more...>", completion = "Ay, what's that? \n\nAh yeah, lots of nice things to be found in those chests out there. Don't seem to be naga things, mind you, and that's kind of strange. Someone else left those here.\n\nHappy to take that off of your hands, though.", objectives = "Ask the Unshackled about the knife.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56241] = { id = 56241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserved Clues", description = "We have found similar chests, as you describe. We believe they were left behind by one that came before the naga.\n\nSome are even locked by odd arcane runes, the naga seem most interested in those.\n\nI know little about them, save that we find them most often in the city ruins.\n\nIf you seek to decipher their history, I would begin there.", completion = "<A simple tome with a small series of runes inscribed along the spine, it appears remarkably well-maintained amongst the ruins. \n\nUpon further inspection, it appears to be a diary of one of the citizens of the city. No doubt the magic that preserves it was intended to allot for the lengthy lifetimes of the elves.>", objectives = "Search in Zin-Azshari for information about the strange arcane chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56242] = { id = 56242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserved Clues", description = "If you find anything else in those chests that you don't need, you feel free to bring it on over my way.\n\nFound a few of them myself. Don't look like they belong to the naga, probably someone that lived in the city.\n\nSome are locked tight by arcane magic, seen the naga taking those back with them. Probably got the good stuff in there.\n\nI don't know much more than that. If you want a history lesson, I'd snoop around the city ruins.", completion = "<A simple tome with a small series of runes inscribed along the spine, it appears remarkably well-maintained amongst the ruins. \n\nUpon further inspection, it appears to be a diary of one of the citizens of the city. No doubt the magic that preserves it was intended to allot for the lengthy lifetimes of the elves.>", objectives = "Search in Zin-Azshari for information about the strange arcane chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56243] = { id = 56243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diaries of the Dead", description = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...>\n\nThen he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas.\n\nOf course, he was bitten on the leg by a lesser summon, and...\n\n<It continues -- not useful, but you surmise there may be more such tomes.>", progress = "<A preserved tome.>", completion = "<You see a glowing lock, and Mardivas' journal is next to it. You glance at the final pages.>\n\nThe rune locks have been stabilized, and organized in such a way that only one with my level of logical acumen would be able to decipher.\n\nOh, to see the faces of the would-be thieves, thwarted! \n\nYes, yes, yes that is it! I shall work on a ward that allows me to view the thieves in the act! Genius, genius, I am.\n\nI simply need a bit more time...", objectives = "Search Zin-Azshari in Nazjatar for additional diaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56244] = { id = 56244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diaries of the Dead", description = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...>\n\nThen he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas.\n\nOf course, he was bitten on the leg by a lesser summon, and...\n\n<It continues -- not useful, but you surmise there may be more such tomes.>", progress = "<A preserved tome.>", completion = "<You see a glowing lock, and Mardivas' journal is next to it. You glance at the final pages.>\n\nThe rune locks have been stabilized, and organized in such a way that only one with my level of logical acumen would be able to decipher.\n\nOh, to see the faces of the would-be thieves, thwarted! \n\nYes, yes, yes that is it! I shall work on a ward that allows me to view the thieves in the act! Genius, genius, I am.\n\nI simply need a bit more time...", objectives = "Search Zin-Azshari in Nazjatar for additional diaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56245] = { id = 56245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Lock", description = "<The lock appears to be secured by a magical mechanism.\n\nIt is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle.\n\nYou look around the room, and see something odd in the water.>", progress = "<The lock hums.>", completion = "<With the puzzle complete, the lock springs open with a satisfying click.\n\nIt seems that Mardivas' devised a series of similar such puzzles with which to secure his belongings.>", objectives = "Solve Mardivas' arcane puzzle to unlock the enchanted lock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56246] = { id = 56246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Lock", description = "<The lock appears to be secured by a magical mechanism.\n\nIt is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle.\n\nYou look around the room, and see something odd in the water.>", progress = "<The lock hums.>", completion = "<With the puzzle complete, the lock springs open with a satisfying click.\n\nIt seems that Mardivas' devised a series of similar such puzzles with which to secure his belongings.>", objectives = "Solve Mardivas' arcane puzzle to unlock the enchanted lock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56247] = { id = 56247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Tale", description = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar.\n\nFrom the sounds of it, he was not well-liked, which worked out for him, as he did not much like others.\n\nYou also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey.\n\nArtisan Itanu will surely enjoy hearing the end of this tale.>", completion = "Ah, how nice to see a proper end to the tale, thank you.\n\nI had always wondered why one would lock up one's dinnerware. If one does not much like or trust others, it becomes more obvious.\n\nDespite all of his efforts, they will end up in your hands, in the end. How droll.", objectives = "Return to Artisan Itanu in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56248] = { id = 56248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Tale", description = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar.\n\nFrom the sounds of it, he was not well-liked, which worked out for him, as he did not much like others.\n\nYou also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey.\n\nFinder Palta will surely enjoy hearing the end of this tale.>", completion = "Hey, thanks for letting me know. Always wondered what was going on with those chests. \n\nNot that I mind free treasures, mind you. All for them.\n\nI'm sure it'd just steam his clams to know that you're going to end up with all of his stuff, ha!", objectives = "Return to Finder Palta in Newhome in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56249] = { id = 56249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Trashmaster", description = "Whatcha got there, richmon? \n\nHa! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted!\n\nSo you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. \n\nYou just give dat ol' thing to me, an Jani will be takin' care o' you...", completion = "Hek hek hek. Thanks for de trade, richmon.\n\nI not be wantin' this thing. It be too stuffy, too high-an-mighty. Not worthy of Jani! But you can have it.\n\nNow be gone. I got offerins' to sort.", objectives = "Give Jani the Trashmaster's Mantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56250] = { id = 56250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Trashmaster", description = "Whatcha got there, richmon? \n\nHa! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted!\n\nSo you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. \n\nYou just give dat ol' thing to me, an Jani will be takin' care o' you...", completion = "Hek hek hek. Thanks for de trade, richmon.\n\nI not be wantin' this thing. It be too stuffy, too high-an-mighty. Not worthy of Jani! But you can have it.\n\nNow be gone. I got offerins' to sort.", objectives = "Give Jani the Trashmaster's Mantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56256] = { id = 56256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", completion = "Well done, {name}!  With the Horde's nose bloodied after the death of their general, we'll have the breathing room we need to explore!", objectives = "Enter Alterac Valley, defeat the Horde general Drek'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56257] = { id = 56257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", completion = "Well done, {name}!  Stormpikes have no hope in this foolish invasion.\n\nHah!  So far, all they've done is get their general killed!", objectives = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56258] = { id = 56258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivus the Forest Lord", description = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, {name}!", progress = "Have you brought us some crystals, {name}?", completion = "Well done, {name}. I will use the power of this charm to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause.", objectives = "Slay Horde and loot a Storm Crystal and return it to Archdruid Renferal in Alterac Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56259] = { id = 56259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokholar the Ice Lord", description = "I come from Thunder Bluff, {race}. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", progress = "Have you come with an offering?", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!", objectives = "Slay Alliance and loot Stormpike Blood and return it to Primalist Thurloga within Frostwolf Village in Alterac Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56260] = { id = 56260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking the Power", description = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion.\n\nI won't spoil it, but ye best get back there as quick as ye can.", completion = "Have we got somethin' fer ye, champion! Yer gonna love this.", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56261] = { id = 56261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Heart", description = "Greetings, Champion of Azeroth.\n\nMOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger.\n\nAt least, we think she's pleased. It's difficult tae tell at times.\n\nRegardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", completion = "The Heart o' Azeroth feels stronger than ever. I wonder what amazing powers might be locked within!", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56262] = { id = 56262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Chamber", description = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference.\n\nMake yer way tae the Chamber o' Heart, champion. Yer talents are needed.", completion = "The Heart o' Azeroth never ceases tae amaze me. Well done, champion!", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56263] = { id = 56263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking the Power", description = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion.\n\nI won't spoil it, but ye best get back there as quick as ye can.", completion = "Have we got somethin' fer ye, champion! Yer gonna love this.", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56264] = { id = 56264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We've Got Crabs!", description = "{name}, you're just in time. Everything's ready for the crab hunt!\n\nOkay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting?\n\nI'm going to level with you, {name}. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people.\n\nIf that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population!\n\nHow many innocent grub worms need to die before we do something, {name}?", progress = "How many innocent grub worms need to die before we do something, {name}?", completion = "That's quite the case of crabs you've got there, {name}. Well done! Please set it down behind the bar and I'll take care of the rest.", objectives = "Collect 12 Crackleclaw Crabs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56265] = { id = 56265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drunk Angry Murlocs", description = "Those no-good Bloodfins ran off with all of the beer!\n\nI've been experimenting with brews that only use ingredients native to Nazjatar, but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck.\n\nMy supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back.\n\nPlease recover the stolen lager from Bloodfin Village before it's too late!", progress = "Please tell me you found the beer.", completion = "Good work, {name}! You've recovered pretty much all of the stolen beer. Those Bloodfins are more trouble than they're worth!", objectives = "Collect 12 Ocean \"Infused\" Lagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56266] = { id = 56266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mgglurky's Mugglrgl", description = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back.\n\nI've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!\n\nI don't know about you, but I definitely don't want to be the main course tonight.\n\nThere were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", progress = "If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!", completion = "You've found it! So this is a mugglrgl? For some reason I thought it would be bigger. Mgglurky will be happy you returned it!", objectives = "Retrieve Mgglurky's Mugglrgl from Bloodfin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56267] = { id = 56267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of N'Zoth", description = "Are you curious how I came to be here, in the Chamber of Heart? \n\nOf course I arrived of my own volition, but there was quite a search for me, for a time.\n\nKalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", completion = "I knew that N'Zoth was powerful, but to reach Ebonhorn in the safety of the Chamber... \n\nWe have to do something about this. None of us are safe.", objectives = "Speak to Kalecgos in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56301] = { id = 56301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go For The Gold", description = "I've heard lot's of stories about dead fathers, mothers, and family treasures. Don't believe any of it. We're all here to get any pirate gold, before these mecha-fools get it first! \n\nIf there's gold to be had here, it's in that fat chest the murlocs are guarding.\n\nKill their chief, empty out the chest, and we'll split it fifty-fifty, since I'm telling ya about it.", progress = "Go get the gold!", completion = "Nice working with ya, here's your share!", objectives = "Recover the Murloc Treasure Bag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56304] = { id = 56304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Life", description = "You there, I require some help.\n\nEveryone where I once called home lost their lives to the flood. I still don't know what became of my father, Corin. \n\nIt pains me to return to the estates, and there are vengeful spirits who haunt the once pristine grounds. Will you help me find out what happened to my father?", completion = "{name}, Corin is being tormented by that naga shadowcaster. \n\nWe have to do something!", objectives = "Accompany Kelya Moonfall into the Highborne Estates to search for the spirit of her father.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56305] = { id = 56305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Fish!", description = "We may need the help of some friends to land this fish!\n\nUse the Hundred-Fathom Lure when you're ready to start.", progress = "Let's fish!", completion = "This will make a great fish story!", objectives = "Catch and kill the Deepwater Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56306] = { id = 56306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family Jewels", description = "Darn pirates stole my jewels... err, I mean my sister's... uh, mom's jewelry. Yeah, that's the story!\n\nPoint is, they stole it, and it's all out there strewn around in the mud, and treasure chests. Maybe on a few of the robots and murlocs.\n\nMy mom's not greedy, she just wants a few of the necklaces with gold and lots of diamonds. I'd pay ya for those.", progress = "Go steal those jewels back for my brother!", completion = "All these jewels for me!", objectives = "Recover 75 Family Jewels", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56308] = { id = 56308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: Aqir Unearthed", description = "Our position is being overrun. The aqir are surging in greater numbers than I've ever seen!\n\nI'm not sure how long we'll be able to hold the line. We need you to drive them back!", progress = "Our men can only hold out so long.", completion = "You have saved our camp, and quite possibly our people.\n\nThank you, {name}.", objectives = "Drive back the Aqir Assault in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56309] = { id = 56309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City of Drowned Friends", description = "Champion, I have a personal favor to ask of you that I do not feel I can ask of any of my sentinels.\n\nThis... this is not on behalf of the Alliance, or the war, or even our battle against Azshara. This is a favor for me.\n\nWhen I was a little girl, my city was attacked by the Legion. Many of the survivors fled here only to drown or worse. I must know their fate.\n\nWill you help me search for signs?", completion = "He... he may be here. Janius... no.", objectives = "Help Shandris Feathermoon search the Drowned Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56310] = { id = 56310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City of Drowned Friends", description = "Champion, I have a personal favor to ask of you. This is not on behalf of the Horde or the war effort.\n\nIt has been over ten thousand years since I last walked these streets. I knew many of these people, even trained some of them.\n\nWill you walk with me as I learn their fates? The road is dangerous, and I do not trust myself to maintain calm as I try to resurface old grief.", completion = "Sivara. Oh Sivara. She was the finest pupil I ever taught. I must find her and ensure she is not locked in eternal torment like these others.", objectives = "Help First Arcanist Thalyssra search the Drowned Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56311] = { id = 56311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ever Drowning", description = "Stay close, Champion. I have some magical items that might help us defend briefly against magic attacks, but Azshara was the greatest mage our kind has ever known.\n\nI do not feel confident that these trinkets will hold back her power for long, or even be usable afterward.\n\nSpeak with me when you are ready.", completion = "The flood has stopped for now. That is good because I do not think I have enough charge left in these items to shield us from another wave like that.", objectives = "Escort Shandris Feathermoon through the Drowned Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56312] = { id = 56312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ever Drowning", description = "Queen Azshara has her eye on us now. We must proceed with caution.\n\nI do not know what she may try but stay close to me. Whatever this threat is we must pass through it if we are to find Sivara.\n\nSpeak with me when you are ready to proceed.", completion = "The flood has stopped for now. That is good because my power is nearly drained.", objectives = "Escort First Arcanist Thalyssra through the Drowned Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56313] = { id = 56313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warbringer", description = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago.\n\nIf you are feeling brave enough to commune with this echo, I will stand guard as you do.", progress = "Be ready for anything.", completion = "We long suspected Azshara's choice. The question becomes, why is she showing us this? What game is she playing this time?", objectives = "Commune with the Memory of the Pact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56314] = { id = 56314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warbringer", description = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago.\n\nIf you are feeling brave enough to commune with this echo, I will stand guard as you do.", progress = "Be ready for anything.", completion = "We long suspected Azshara's choice. The question becomes, why is she showing us this? What game is she playing this time?", objectives = "Commune with the Memory of the Pact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56315] = { id = 56315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Made Their Choice", description = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well!\n\nThose who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. \n\nI am almost afraid of what we will find if we do find my friend.\n\nWait, did you hear something?", progress = "Thrice damned Azshara. Her evil knows no bounds.", completion = "I cannot thank you enough for helping me say farewell to my friend, {name}. I am in your debt.", objectives = "Aid Shandris Feathermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56316] = { id = 56316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Made Their Choice", description = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well!\n\nThose who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. \n\nI am almost afraid to find Sivara.\n\nWait, did you hear something?", progress = "Thrice damned Azshara. Her evil knows no bounds.", completion = "Sivara could have defeated us at any time. Why are they toying with us? \n\nAt any rate, champion, again I find myself in your debt. Thank you for helping me, even if the answers we found were more horrifying than I could have anticipated.", objectives = "Aid First Arcanist Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56319] = { id = 56319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quickcharge Contract", description = "Wondrous news, dear test subject!\n\nMy dear brother and I have restored 65% of the functionality of our research laboratory.\n\nWe are hoping to resume our regular research schedule shortly, but require a fresh batch of brave test subjects to help us push the laws of nature and science to their limits!\n\nIf you're interested, you'll just need to agree to our standard verbal contract first...", progress = "How can I help you, dear test subject?", completion = "Welcome to the Quickcharge team, dear test subject.\n\nWhat a wondrous day this is!", objectives = "Agree to the Quickcharge Contract.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56320] = { id = 56320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Charge is Free!", description = "Do you feel the energy rippling through the ground here, my dear test subject?\n\n<Flip inhales deeply.>\n\nWithout that constant bristle of electricity, nothing of any meaning would exist.\n\nMy dear sister and I have tapped into a high-voltage power line buried here, but the real juice is over in Bondo's Yard. He selfishly hoards access to the heftiest power line in Mechagon!\n\nIf you want to recharge your empty energy cells, you're going to have to get access to the Charging Station from Flux.", completion = "Flux is rude, crude, and I suspect more than a little unglued.\n\nBe careful with that wondrous energy cell. Those little packs of power are worth their weight in gold out here in Mechagon!", objectives = "Gain access to the Charging Station in Bondo's Yard, then use it to charge an Empty Energy Cell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56321] = { id = 56321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Corin", description = "My father is being tortured by that naga!\n\n{name}, I need you to help me save him. We can't let his spirit be a slave to the naga. \n\nHurry, if we don't act now he will end up like the rest of them!", completion = "Thank you, {name}. My father and I are eternally grateful for what you did.", objectives = "Defeat Shadowcaster Vixtris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56322] = { id = 56322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contained Alemental", description = "<As the brew is returned to its natural, dormant form, a strange keg appears.\n\nPerhaps Brewmaster Tsing knows more about such a strange occurrence.>", completion = "Everything has a spirit to it. From the clouds in the sky to the worms in the ground, life is woven through the entire world.\n\nBrew is no different. Created with such love, such care... it only requires a spark to spring to life in front of our very eyes.", objectives = "Talk to Brewmaster Tsing in the Brewfest grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56324] = { id = 56324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Charge Ain't Free!", description = "You lookin' to charge some energy cells off of our tower of power?\n\nI ain't surprised - everyone is.\n\nAnd everyone PAYS. You got that or I got ta say it again?\n\n<Flux spits behind her.>\n\nI can tell you're a first-timer. Bondo's got a special deal for you flashfoots.\n\nSmall access fee, one charge only.\n\nDeal? You ain't gettin' any other offers.", progress = "You lookin' to charge some energy cells off of our tower of power?\n\nI ain't surprised - everyone is.\n\nAnd everyone PAYS. You got that or I got ta say it again?\n\n<Flux spits over her shoulder.>\n\nI can tell you're a first-timer. Bondo's got a special deal for you flashfoots.\n\nSmall access fee, one charge only.\n\nYou ain't gettin' any other offers.", completion = "You're authorized for one charge.\n\nHold up your empty energy cell to the Charging Station to proceed.\n\nNo double-charging. I've got my eyes on you.", objectives = "Pay Flux's access fee, then use the Charging Station to charge an Empty Energy Cell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56325] = { id = 56325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing Tides", description = "We are out of time. We must gain control the Tidestone of Golganneth and the Javelin is our best shot at piercing the barrier surrounding it.\n\nThe guardian is formidable, but must be defeated if we are to take the fight to Azshara. What forces we have will be arrayed below, just outside their encampment.\n\nI would trust you with the Javelin of Suramar, {name}. We will need your strength in the coming battle.", progress = "If we do not take the Tidestone, we are finished.", completion = "Quickly, the Tidestone!", objectives = "Assault the naga camp and seize control of the Tidestone of Golganneth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56326] = { id = 56326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravenous Rescue", description = "A conspiracy of ravens is preying on citizens of Rustbolt! It's most unacceptable! \n\nPrince Erazmin has asked me to rescue as many citizens as I can, but I could use your help. I've tracked the ravens to this hill. We blast the ravens out of the sky, and you rescue the mechagnomes.\n\nUse my marker gun if you need help bringing the ravens down.", progress = "Let's get to it!", completion = "You've lived up to your reputation.", objectives = "Rescue 8 injured mechagnomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56327] = { id = 56327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chopped Bots", description = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us!\n\nUse the Bot-Energizer to bring me dead bots, and we'll break them into spare parts.", progress = "Re-animate dead bots and bring them to me!", completion = "I love those spare parts! You're can grind up bots here anytime you want!", objectives = "12 Re-animated bots delivered to Bolten Springspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56328] = { id = 56328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Not Drink", description = "These troggs watch everything we do.  \n\nThey see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines!\n\nWe need that oil back, before they drink it all!", progress = "Get that oil back quick!", completion = "Ya done good work.", objectives = "Recover 12 containers of Stolen Oil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56334] = { id = 56334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bots Gone Wild", description = "It's loose up there!\n\nI told them not to do it, but they didn't listen. Now it's gone out of control and killed everyone up there. It's an experimental Whirlbot. They never should have built it!\n\nYou need to stop it before it comes down here looking for more victims!\n\nKill the Whirling Zap-O-Matic.", progress = "You need to stop it.", completion = "You performed better than those that build the bot.", objectives = "Whirling Zap-O-Matic slain", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56335] = { id = 56335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanna Charge? Gotta Pay!", description = "You lookin' to charge some energy cells off of our tower of power?\n\nI ain't surprised - everyone is.\n\nAnd everyone PAYS. You got that or I got ta say it again?\n\n<Flux spits behind her.>\n\nI can tell you're a first-timer. Bondo's got a special deal for you flashfoots.\n\nSmall access fee, one charge only.\n\nDeal? You ain't gettin' any other offers.", progress = "You lookin' to charge some energy cells off our tower of power?\n\nSave your sob stories. Everyone pays.\n\n<Flux spits over her shoulder.>\n\nNo exceptions.", completion = "Limited access granted.\n\nCharge whatever you want. Don't break anything.\n\n<Flux spits over her shoulder.>\n\nMost importantly, mind your own damn business.", objectives = "Pay Flux's access fee, then use the Charging Station to charge an Empty Energy Cell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56336] = { id = 56336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran. Go out and kill any you find and bring at least fifty to Ecilam the Mage near the campfire in Stormshield Stronghold.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort.", objectives = "Ecilam in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56337] = { id = 56337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran.\n\nGo out and kill any you find and bring at least fifty Artifact Fragments to Fura the Mage in Warspear Outpost.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort.", objectives = "Fura in Warspear Outpost wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56338] = { id = 56338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volrath Must Die", description = "The Horde are getting in our way of completing our mission here in Ashran. Their leader is High Warlord Volrath. He must be put down.\n\nPush forth through the center road, enter Warspear and slay Volrath.", completion = "Well done. That will give the Horde something to think about next time they decide to test us here in Ashran.", objectives = "Slay High Warlord Volrath found in the Horde base Warspear within Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56339] = { id = 56339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tremblade Must Die", description = "This battle in Ashran has waged on long enough. It appears they're being led by Grand Marshal Tremblade. If she falls, the Alliance will crumble.\n\nPush forward through the center road, make your way into their keep and take down Tremblade.\n\nFor the Horde!", completion = "That's what I like to see, good work {class}.", objectives = "Slay Grand Marshal Tremblade found in the Alliance base Stormshield Keep within Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56341] = { id = 56341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbrew Cog", description = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines.\n\nPerhaps your Dark Iron allies would be interested in hearing of your victory.>", completion = "<Verra spits on the cog.>\n\nThat Direbrew is a piece o' work. He's been a contrarian since before we even joined the Alliance. I'm not surprised he's still attackin'. \n\nAll he thinks about is brew and causin' chaos! Not to say that I don' love those things too, but there are other things in life!\n\nThanks for takin' care o' him.", objectives = "Talk to Verra Fireblood in the Brewfest grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56344] = { id = 56344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Darkmaul Citadel", description = "We've rescued everyone except for the expedition's captain. Lindie's Scout-o-Matic spotted her just outside Darkmaul Citadel.\n\nMeredy has come up with an... interesting plan to rescue the captain. It may be our only chance.\n\nCome. We'll convene in the shadow of Darkmaul Citadel, and there we will begin our rescue mission.", completion = "All right, {name}. I hope you're a good actor, because you're about to play to a very tough crowd.", objectives = "Meet Lady Jaina Proudmoore outside of Darkmaul Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56346] = { id = 56346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Technology", description = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage.\n\nPerhaps Instructor Ulooaka back at Mezzamere could help you repair this core and put it to use against the naga invasion.>", completion = "What's this you've brought me?\n\n<Instructor Ulooaka looks over the broken power core and arcs an eyebrow. You ask him if he thinks it could be used against the naga.>\n\nActually, I believe it could. But probably not in the way you think.", objectives = "Bring the Broken Power Core to Instructor Ulooaka in Mezzamere.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56347] = { id = 56347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abyssal Opportunity", description = "I believe, {name}, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level.\n\nBut we're getting ahead of ourselves. The first thing we need to do is repair this device.\n\nIt'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region.\n\nHowever, Artisan Okata is great at collecting materials like the ones we need. I'd check with him to see what he's got.", progress = "How goes the hunt for the materials?", completion = "This should be plenty, {name}. I'll get started on repairing it right away.", objectives = "Acquire 15 Abyssal Shards from Artisan Okata.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56348] = { id = 56348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Palace: We Can Make It Stronger...", description = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy.\n\nOf course that will require stronger materials to upgrade and the only place I can think of is in the Eternal Palace.\n\nAzshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", progress = "How goes the search for those items?", completion = "Yes, these will do nicely. Good work, {name}.\n\nI'll get started right away on upgrading the core.", objectives = "Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56349] = { id = 56349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Palace: Pushing the Limits", description = "Now that we know how to increase the potency of this tool, I think we can push its capabilities even further.\n\nBring me back more of those ornaments. LOTS of them.\n\nLet's see just how far we can make this go.", progress = "Any luck on retrieving more of those ornaments?", completion = "Wow, that's...a lot!\n\nAlright, let's see what this thing can do.", objectives = "Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56350] = { id = 56350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Palace", description = "We cannot hide here forever, {name}. Azshara must be dealt with.\n\nIt would be an act of folly to assault her palace without knowing what defenses she has in place. I dispatched a scouting team while you were gone, but they have not reported back.\n\nI'm getting concerned, {name}. Let me know when you're ready and I'll perform a ritual to see what has happened to our scouts.", progress = "Are you ready?", completion = "The Tidestone! Of course...", objectives = "Speak with Lady Jaina Proudmoore to observe the scouting party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56351] = { id = 56351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Palace: Pushing the Limits", description = "Now that we know how to increase the potency of this thing, I think we can push its capabilities even further.\n\nBring me back more of those ornaments. LOTS of them.\n\nLet's see just how far we can make this go.", progress = "Any luck on retrieving more of those ornaments?", completion = "Wow, that's...a lot!\n\nAlright, let's see what this thing can do.", objectives = "Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56352] = { id = 56352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Palace: We Can Make It Stronger...", description = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy.\n\nOf course that'll require stronger materials to upgrade and the only place I can think of is in the Eternal Palace.\n\nAzshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", progress = "How goes the search for those items?", completion = "Yes, these'll do nicely. Good work, {name}.\n\nI'll get started right away on upgrading the core.", objectives = "Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56353] = { id = 56353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abyssal Opportunity", description = "I believe, {name}, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level.\n\nBut we're getting ahead of ourselves. The first thing we need to do is repair this device.\n\nIt'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region.\n\nHowever, Finder Pruc is great at collecting materials like the ones we need. I'd check with him to see what he's got.", progress = "How goes the hunt for the materials?", completion = "This should be plenty, {name}. I'll get started on repairing it right away.", objectives = "Acquire 15 Abyssal Shards from Finder Pruc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56354] = { id = 56354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Technology", description = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage.\n\nPerhaps Rolm back at Newhome could help you repair this core and put it to use against the naga invasion.>", completion = "What's this ya brought me?\n\n<Rolm looks over the broken power core and arcs an eyebrow. You ask him if he thinks it could be used against the naga.>\n\nActually, I believe it could. But probably not in the way ya think.", objectives = "Bring the Broken Power Core to Rolm in Newhome.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56355] = { id = 56355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Tested", description = "A weapon like this could really turn the tide against King Mechagons Troops. Let's go see how their gear matches up against our new toy.\n\nTake out King Mechagon's Sentries wherever you can find them", progress = "Go kill something!", completion = "This is what I like to see!", objectives = "Eliminate 10 Upgraded, Anodized, or Corroded Sentry wherever you find them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56356] = { id = 56356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Palace: Queen's Gambit", description = "The way is clear. The palace awaits, {name}.\n\nWithin the Vainglorious holds court with an old god. Defeating her will be no small feat. \n\nMake no mistake, Azshara is one of the most powerful sorceresses alive. We cannot underestimate her power or her planning, for she has had thousands of years to prepare for us. Nevertheless, she must be defeated.\n\nWe are ready when you are. Shall we finally accept her invitation?", progress = "We cannot rest easy knowing that she still holds power here.", completion = "This is only the beginning....", objectives = "Defeat Queen Azshara in the Eternal Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56358] = { id = 56358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Palace: Queen's Gambit", description = "We have opened the way to the palace. We must end this.\n\nQueen Azshara is the most powerful sorceress in existence. She mastered magics thousands of years before our archmagi were even born.\n\nStill, we must prevail. If not, she and her dark patron will remake all of Azeroth to their desires.\n\nChampion, we must defeat Azshara. Are you with us?", progress = "Such power, brought to ruin....", completion = "She is gone, but this is far from over.", objectives = "Defeat Queen Azshara in the Eternal Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56361] = { id = 56361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Tidespray Linen", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56362] = { id = 56362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Tidespray Linen", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 20 Storm Silver Ore to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56363] = { id = 56363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Frenzied Fangtooth", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56364] = { id = 56364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Frenzied Fangtooth", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 20 Storm Silver Ore to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56365] = { id = 56365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Kind, Rewind", description = "You exist here due to a time anomaly, but you must return to your own time and help us there.\n\nThe Visual Holo Sphere from the Vaultbot nearby contains the data necessary to defeat King Mechagon before he can use the Mechoriginator.\n\nDeliver the Visual Holo Sphere to me in your reality. With luck I will be able to rewind history and prevent this existence from ever happening.", progress = "You will have to return to your time period.", completion = "Let's hope that you bringing me this, is not what triggers that alternate reality.", objectives = "Deliver the Visual Holo Sphere to Izira Geasworn in Rustbolt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56370] = { id = 56370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break a Few Eggs", description = "The naga are using these caverns as a hatchery for their deadly deepcoil serpents.\n\nThese deepcoil serpents are especially dangerous because they have been infused with dark void magic.\n\nWe must put a stop to this operation before it is too late. The naga forces are already quite powerful. I do not wish to imagine what would happen if Azshara also had an army of these deepcoil serpents as well.\n\nOur only hope is to destroy the deepcoil eggs before they hatch.", progress = "Have you destroyed the deepcoil eggs?", completion = "You have done well, {name}. We cannot allow the naga to amass an army of these mutated deepcoil serpents. We will need to keep a close eye on this place...", objectives = "Destroy 10 Deepcoil Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56371] = { id = 56371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Young Twilight Scale", description = "<A partially-grown scale from a young twilight whelp.\n\nMore and more twilight dragons are appearing once again. This seems suspicious.\n\nYou should show the scale to Eryna above Grim Batol in the Wetlands, perhaps she has seen something recently.>", completion = "Welcome, I see you noticed the whelps. They appeared recently, along with more members of the flight coming and going from the citadel. \n\nI have indeed been observing strange happenings down below.\n\nI sense a great power has manifested. Something awakened in the depths, perhaps? One thing is certain -- the flight is mobilizing at someone's command.\n\nI will continue to relay all I find to my flight and your Speaker, thank you for your assistance.", objectives = "Show the scale to Eryna above Grim Batol in the Wetlands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56372] = { id = 56372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen Totem", description = "<The hozen have been successfully chased away, and Brewfest saved once again.\n\nThe question asks itself, though: How did hozen get to Dun Morogh? Perhaps you should ask somebody who has experience in navigation and travel.>", completion = "Just because I arrived to Azeroth on a ship that flew through the stars doesn't mean that I know how... navigation works.\n\nI've never even seen a hozen, let alone one with wings!\n\nPerhaps they held hands as they flew through the sky? Your guess is as good as mine.", objectives = "Talk to Arcti in the Brewfest grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56373] = { id = 56373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gulper Ate The Rolly", description = "The Bubble-eyed Rolly used to be plentiful in the nearby pond.  Last week they all started to vanish!\n\nA large water elemental has been swallowing all the fish! They are still alive, just swimming around inside the elemental now.\n\nI need you to kill that elemental, and catch three Bubbly-eyed Rolly so I can examine their condition.", progress = "Did you kill that elemental?", completion = "You saved a lot of Rollys today!", objectives = "Kill the Rolly Gulper and catch 3 Bubble-eyed Rolly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56374] = { id = 56374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titanic Problem", description = "We've no time tae waste. \n\nWithout the Forge of Origination, Azeroth is left vulnerable tae N'Zoth's corruption. Not tae mention it holds a weapon capable of wipin' out all life on Azeroth!\n\nWe'll need tae head over tae the forge right away. MOTHER can hold down the fort here.\n\nHurry on, I'll meet ye there.", completion = "Ye got here just in time, {name}.\n\nThis whole place is overrun!", objectives = "Meet Magni Bronzebeard at the Halls of Origination in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56375] = { id = 56375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Ramkahen", description = "It looks like we're gonna have tae wait a spell while MOTHER figures out what tae do with the forge.  In the meantime we'll want tae try to make sure nobody tries tae do any more damage here.\n\nYe should check in on the tol'vir in Ramkahen. I know ye've helped them in the past, so they might be able tae help us keep the forge out o' the wrong hands.", completion = "Welcome to Uldum, {class}. \n\nI wish we could have offered you a warmer welcome, but I'm afraid my people find themselves once again in a dire situation.", objectives = "Meet King Phaoris in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56376] = { id = 56376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surfacing Threats", description = "The tol'vir take the protection of the titans' constructs here in Uldum as a sacred duty. However, our numbers have dwindled, and we face greater threats with each day.\n\nEven with the strength of our new allies, we will only be able to hold these enemies back for so long.  Should any of them surge in power, they may still be able to overwhelm us and endanger the forge. This is where your assistance is needed.\n\nSpeak to High Commander Kamses to assess our current situation.", completion = "The threat has abated... for now.\n\nOur scouts will continue to monitor enemy movements. With any luck we should be able to keep them at bay before they can make a move on the forge.\n\nThank you, {name}.", objectives = "Complete an Assault in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56377] = { id = 56377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Onward", description = "Thanks fer helpin' me back there at the forge. It's vexin' that N'Zoth was able to infiltrate it so quickly, but at least we arrived in time tae keep it from bein' completely wrecked!\n\nNow comes the task of gettin' her back tae a hundred percent. MOTHER has been workin' on a solution, and we think we've got a plan.", progress = "Aye?", completion = "It looks like we're in for quite an adventure, champion!", objectives = "Return to Magni Bronzebeard at the Chamber of Heart and learn about the fate of the Forge of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56378] = { id = 56378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Crew", description = "I can't believe it. Almost the entire fleet.. lost! \n\nWe need to have ships out there on missions supporting our efforts, but how am I supposed to do that now?\n\nIf we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", completion = "Well, I suppose that's better than nothing. Let's get to work.", objectives = "Find and rescue the missing crew members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56379] = { id = 56379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Crew", description = "I can't believe it. Almost the entire fleet... lost! \n\nWe need to have ships out there on missions supporting our efforts, but how am I supposed to do that now?\n\nIf we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", completion = "Well, I suppose that's better than nothing. Let's get to work.", objectives = "Find and rescue the missing crew members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56380] = { id = 56380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grounded", description = "One of King Mechagon's older Aerial units is having mechanical problems and is grounded nearby. \n\nThey're trying to get it repaired, so we need to act fast while it's vulnerable.\n\nDestroy the Aerial Patroller XZ-2 before they can get it repaired.", progress = "Did you kill the Aerial Patroller XZ-2?", completion = "That's one less threat to our forces!", objectives = "Destroy the Aerial Patroller XZ-2", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
