quests[56421] = { id = 56421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Numeric Cylinder", description = "<R33-DR is looking for this item.>", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
quests[56422] = { id = 56422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Ghostly Wings", description = "We will meet you back where our journey began, {name}. \n\nCorin and I have been separated for many years. We have so much to catch up on. \n\nAs a token of our gratitude we will remain in the area to help you in your travels through this cursed land.", completion = "Thank you, {name}.\n\nBecause of your efforts, we have some the peace of mind that was long lost.\n\nMy father and I are at your service.", objectives = "Return to Kelya Moonfall in Zin-Azshari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56423] = { id = 56423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Large Storage Fragment", description = "<R33-DR is looking for this item.>", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
quests[56424] = { id = 56424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rust Covered Disc", description = "<R33-DR is looking for this item.>", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
quests[56425] = { id = 56425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scorched Data Disc", description = "<R33-DR is looking for this item.>", progress = "Deliver the item to R33-DR.", completion = "Data successfully purged." }
quests[56429] = { id = 56429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up Against It", description = "I don't like the sound of that... It sounds like an army!\n\nWe need to investigate.\n\nTry not to draw too much attention as we take a look. If there's an army down there, we'll need to move quickly to find refuge.", progress = "These naga move with a single purpose!", completion = "These naga wear out their welcome quickly.", objectives = "Move deeper into Nazjatar with Lor'themar and Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56430] = { id = 56430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defensive in Death", description = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Rolm will have more insight on how to keep this herb from defending itself.>", completion = "Zin'anthids are no mere plant, {name}. They are living beings and as such, know when a predator is trying to harvest them. And yes, even in death they defend themselves.\nIf you wish to harvest all they have to offer, you must lure them into a false sense of security. Here, let me show you a technique I know.", objectives = "Ask Rolm about the tentacles of the Zin'anthid.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56431] = { id = 56431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ounces of Osmenite", description = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Rolm knows of still a better way to mine this ore.>", completion = "Ah yes, that's due to the fragile nature of the ore. You need to adjust your style a bit.\n\nInstead of heavy, powerful swings, try picking away at the edge of where the ore meets the rock.\n\nLike peeling the skin off a fruit. Here, let me show you what I mean...", objectives = "Ask Rolm about the Osmenite Shards.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56432] = { id = 56432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seams to be a Problem", description = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with.\n\nIt may be worth talking to Rolm to see if there's a way to prevent this loss from happening.>", completion = "The seams that osmenite flows through are structurally different than that of their mere deposits.\n\nIf you want to harvest the full amount of osmenite from a seam, you'll have to ignore the ore all together and go for the rock surrounding it.\n\nIt's a bit counter to how you normally mine, but trust me, you'll be pleasantly surprised with the results.", objectives = "Ask Rolm about the Osmenite Dust.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56433] = { id = 56433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drowning the Alliance", description = "The Alliance continue to pursue us, they will not disrupt our plans any further. Drive their champions into a watery grave.", completion = "There is no way the Alliance will defeat us, even here.", objectives = "Kill 25 Alliance players in Nazjatar while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56434] = { id = 56434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Junkbrat and Roadtrogg", description = "Responsible for a spree of mayhem and chaos throughout the Heaps, resulting in the theft of energy cells, spare parts, and the consumption of Improbable Mechano-Chicken Wings without payment.\n\nSpecial caution around Roadtrogg, who has demonstrated a violent attitude towards living things.\n\nElimination of these two felons is of the highest priority.", completion = "It's about time we saw the last of those two!", objectives = "Eliminate Junkbrat and Roadtrogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56436] = { id = 56436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Skull", description = "<Inside of the gelatinous remains of the slime you find a small skeleton.\n\nSomeone in Rustbolt might be missing. \n\nYou pick up the skull, it might still be able to be identified.>", completion = "Another one? Don't worry, there's no tragedy behind this skull. It's not real.\n\nWhen we first started finding the skeletons, we feared the worst. Our children getting lost in the wastes and devoured!\n\nBut no, the kids are safe.\n\nIt's him, he's tormenting us. King Mechagon. Heard he has some new technology, calling it \"thrice die mentioned smithing.\" Lets him make whatever he wants.\n\nAnd he chooses to make fake baby skeletons.\n\n<Vera shakes her head.>\n\nJust toss it in the grinder with the rest.", objectives = "Show the Small Skull to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56437] = { id = 56437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rusty Tube", description = "<The malfunctioning junkbot is now a mere heap of metal, its signature tube poking out of the remains.\n\nYou remove the tube. The citizens of Rustbolt seem to trade in junk, maybe someone will want it.>", completion = "A tube? A rusty tube. Aw, you shouldn't have!\n\n<Vera laughs and then looks closer at the tube.>\n\nHold a moment, an 18 unit tube? You're telling me the circumference of this tube is 18 standard units. That's what I'm seeing here with my unit gauge.\n\nHoly manufactured light, that is just perfect for my hair dryer.\n\nYou're the best! Well, best tube-finder, at least.", objectives = "Show the Rusty Tube to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56438] = { id = 56438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flashing Siren", description = "<Despite the robot being destroyed, the siren continues flashing.\n\nClearly this was a key sentry of King Mechagon. The citizens of Rustbolt will want to know of its demise.>", completion = "Gold trim on the base. This must be from that golden robot patrolling the city outskirts?\n\nNice hit, that thing has been a pain in our side for as long as I can remember.\n\nNot because it actually catches us--it's terrible at that.\n\nNo, the thing wanders into the city in the middle of the night, and looks in our rooms! Just imagine -- you're sound asleep, then the room is lit up bright red, and there's a robot just standing there, looking at you.\n\nIt wanders away eventually, but wow, how rude!", objectives = "Show the Flashing Siren to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56439] = { id = 56439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanical Egg Sac", description = "<You find a mechanical egg sac inside of the defunct spiderbot.\n\nThis doesn't make any sense, robots don't reproduce this way.\n\nOr do they?\n\nSomeone in Rustbolt might have the answers.>", completion = "Well that's creepy.\n\nMaybe King Mechagon thought we'd be scared of mechanical creatures that could reproduce.\n\nI could see him doing something like that. Reveals his own fears more than ours.\n\nOr maybe the mechanical spiders are... evolving.\n\nCan programs do that?\n\n...\n\nAm I a program?\n\n<Vera sits down to think.>", objectives = "Show the Mechanical Egg Sac to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56440] = { id = 56440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can of Critter Spray", description = "<Inside the wreckage of the robot, you find a sealed can of anti-critter spray.\n\nDestroying all life, down to the rats, seems cruel but on par for King Mechagon.\n\nSomeone in Rustbolt might be able to provide additional insight.>", completion = "Oh, yeah, you didn't hear? Proclamation 7: King Mechagon outlawed non-mechanicals smaller than a baby.\n\nHe thought that was so important that it was his SEVENTH proclamation ever made.\n\n<Vera shakes her head.>\n\nThe king hated bugs, rats, anything uninvited that always finds its way into a city. So, he made them illegal. \n\nHe arrested rabbits, squirrels, even fish. Held tiny trials, sentenced them to mechanization, or death, or exile.\n\nHe made those flying robots to deal with any that remained.", objectives = "Show the Can of Critter Spray to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56441] = { id = 56441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluckbox", description = "<In the sparking, smoldering wreckage of Unit 35, you find a small, black cube.\n\nIt looks to be made of a metallic substance and appears unharmed.\n\nLooking closely, you see a single word imprinted in the metal -- \"Cluckbox.\"\n\nThis particular mechanical fowl was operating quite strangely. Someone in Rustbolt will probably want to investigate.>", completion = "Is that the cluckbox from that rust-blooded Unit 35? I hate that thing!\n\n<Vera grabs the box from you and throws it to the ground. She stomps on it a few times, then once more for good measure.>\n\nSomeone programmed that thing to wake up the island at dawn every morning! Who does that?\n\n<Vera glares in the direction of the city.>\n\nIf you see that thing show up again, smash it good for me.", objectives = "Show the Cluckbox to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56442] = { id = 56442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Unit 6", description = "<Unit 6 sits here, nonfunctional following your attack.\n\nThere is something different and unsettling about this mechanical frog. It appeared to be mimicking frog behavior, but in a way that seemed wrong somehow.\n\nNone of the other mechanical frogs in the area behave similarly.\n\nInstead of taking back only part of the unit for inspection, you pocket the entire frog. It's pretty small, after all.>", completion = "Is that one of the mechanical critters? Ah, one of the dark metal ones.\n\nI've never seen one up close. I kept my distance because they never felt... right to me.\n\nNo one in Rustbolt knows where they came from. Perhaps King Mechagon sent them to watch the other critters as they mechanized? He would be the type to want to watch their suffering.\n\nMost think they're here to spy on us. You shouldn't have brought the whole thing back to the town. Just grab an eye, or a liver, next time.", objectives = "Show the Broken Unit 6 to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56443] = { id = 56443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanical Eye", description = "<As the mechanical body of Unit 17 crumples into a heap, one eye lights up.\n\nYou hear a popping noise, and the eye flies from the head, aided by a small explosion.\n\nYou pick up the eye and notice it twitch a few times, then power down.\n\nThe citizens of Rustbolt seem to like junk, maybe they'll be interested in this.>", completion = "You retrieved this from a mechanical marmot? It must have been that one with the smoke-colored metal.\n\nDid I ever tell you my story about that sinister Unit 17?\n\nSo there I was, browsing the scrap heap for junk, like you do. Suddenly, it's right in front of me -- Unit 17. \n\nI froze. Did it see me? What would it do? I took one step backwards, it twitched, I yelped.\n\nThen it blared at me in a tone I will never forget.\n\n\"Error 74.\"\n\nI ran back as fast as my legs could take me.\n\n<Vera shudders.>", objectives = "Show the Mechanical Eye to Vera Lonelycog in Rustbolt on Mechagon Island.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56444] = { id = 56444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiggletail's Poking Fork", description = "<The tenacious tine of the vanquished prince.\n\nIt does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted.\n\nYou pocket it anyway. Perhaps Artisan Itanu would be interested?>", completion = "Ah hello again, have you more treasures from the deep?\n\nOh, an eating instrument. You will have to convince me of its value here, friend.\n\nIt came from a small naga? Hm, yes. I have seen one such as you describe. \n\nI have thought many long hours about where it may have come from. \n\nI have concluded that it is best not to think on it.\n\nI will gladly take this fork from you to aid in removing the barnacles from my home, though.", objectives = "Show Wiggletail's Poking Fork to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56445] = { id = 56445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiggletail's Poking Fork", description = "<The tenacious tine of the vanquished prince.\n\nIt does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted.\n\nYou pocket it anyway. Perhaps Finder Palta would be interested?>", completion = "Oh hey, how's it going? Got anything to sell? Or buy?\n\nA fork? You brought me a fork? \n\nIt came from a tiny naga? Oh, yeah, I've seen that one. We talk about it all the time! What even is that thing?\n\nIs it a baby naga? Or maybe just a vision from the deeps? Where did it come from?\n\nI have no answers for you, friend. But I'll take that fork -- it's almost dinner time.\n\nThink I'll have the fish.", objectives = "Show Wiggletail's Poking Fork to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56446] = { id = 56446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leathery Venom Gland", description = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind.\n\nThis toxin appears to be very potent. It would be best to bring it back to Mezzamere.>", completion = "Friend, let me take that from you, it is best not to handle the venom for too long.\n\nThe naga tame the snapdragon with ease, but we have more difficulty. They seem to have a natural affinity for them. I envy them somewhat, the creatures are both vicious and loyal.\n\nThe venom they spit is deadly. I have only known one to truly master it, a naga commander. We believe she feeds on the substance to give herself immunity. I do not know how this is possible, she must be a terror in combat.", objectives = "Show the Leathery Venom Gland to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56447] = { id = 56447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Digested Deepcoral Pod", description = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods.\n\nYou've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays.\n\nThis may explain their strange ability to fly.\n\nArtisan Itanu might know more.>", completion = "Hello again, have you come to trade?\n\nAh yes, the coral produces such pods. The fathom rays have a liking for them, we can sometimes lure one into a trap with them, to tame or consume.\n\nThe pods are filled with a gas of some sort, I have never ventured to breathe it myself, but I surmise this diet now keeps the rays aloft.\n\nThe creatures of the deeps have not seen the air before, yet I could not have foreseen such an outcome. It is fascinating.", objectives = "Show the Half-Digested Deepcoral Pod to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56448] = { id = 56448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Molted Spineshell", description = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar.\n\nThe spines that stick out from it are quite sharp.\n\nArtisan Itanu may have some use for this.>", completion = "That is quite a pretty shell, we find them around when the spine crabs molt.\n\nSpine crabs lurk in the deep trenches, waiting on large fish to spear and devour. The beasts of our waters are not as kind as yours.\n\nThe shells themselves are not useful to us -- they become flimsy and brittle over time.\n\nOnce, the children would fill them with sand and hang them on the coral as decorations.\n\nThat was long ago.\n\n<Itanu tosses the shell into the sand with a deep sigh.>", objectives = "Show the Molted Spineshell to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56449] = { id = 56449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearlescent Shell", description = "<A large, hardened shell of a vanquished hermit crab.\n\nThe shell itself was much larger than the crab, and shines in different colors when you look at it at different angles.\n\nSurely someone back at Mezzamere would be interested in this beautiful shell.>", completion = "Ah, a hermit crab shell. The crabs here are not easy to hunt, nor are they worthwhile. The size of the crab is so small, barely makes for a single meal.\n\nThe shells themselves are quite useful. We use them in making spear tips, shields, even cookware and pots. They are quite versatile and do not lose their durability with time.\n\nI shall add this one to the supplies, with our thanks.", objectives = "Show the Pearlescent Shell to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56450] = { id = 56450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eel Jelly", description = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime.\n\nThe slime coats your hands and arms, and seems quite difficult to remove.\n\nOne of your deep sea allies may know more about it.>", completion = "Eel jelly? What have you gotten yourself into? Eels, I would guess.\n\nHere, let me remove it from you. We have many uses for it, if you can believe it. Few other things can make things slick, here beneath the waves. You may find it useful as well.\n\n<Itanu rubs some jelly on your arms and legs.>\n\nYou will slide between coral like the tides now, friend.", objectives = "Show the Eel Jelly to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56451] = { id = 56451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mottled Hydra Scale", description = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors.\n\nThere appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", completion = "Ah, a hydra scale, we do have a fair bit of them around here.\n\nThey have three matriarchs leading their packs. Each one has attempted to gain dominance over the area for years, yet they always fail.\n\nThe naga amuse themselves by sending slaves into the area to be devoured.\n\nThey are friends of none, we had best leave them be.", objectives = "Show the Mottled Hydra Scale to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56452] = { id = 56452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Organ", description = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb.\n\nThe octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them.\n\nSomeone in Mezzamere may know more.>", completion = "The organ from a mind-squid, yes, I am familiar with them.\n\nThe children of Ozumat flood the deeps, too numerous to count. \n\nThey attack our thoughts with the aid of this organ. It makes a sound that speaks directly to the mind.\n\nLet me show you.\n\n<Itanu pushes on the organ, and your mind is assailed by a deafening psychic scream.>\n\nThe very creature itself seems built to harass the mind, and service the old ones.\n\nI will dispose of this now, away from the camp.", objectives = "Show the Strange Organ to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56453] = { id = 56453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overgrown Stone", description = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants.\n\nYou have not seen many such creatures in the deeps. Perhaps there is a story to them.\n\nOne of your new undersea allies may know more.>", completion = "Oh hello, what have you there?\n\nA fragment from a kelp-covered elemental? Most fortuitous. Such stones can be used to enhance the growth of most sorts of plants that we know of.\n\nAt times, I use them to grow healing wraps for us, when I can find them. The elementals themselves are quite rare.\n\nI thank you for this donation.", objectives = "Show the Overgrown Stone to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56454] = { id = 56454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crackling Mandible", description = "<The mandible of a tidal guardian, still crackling with electricity.\n\nOne of your new allies might have a use for this.>", completion = "Oh, let me handle that with care, I do not want another shock.\n\nYou have met the tidal guardians, then? They have lived in the naga caves for as long as I can recall, serving their masters faithfully. I have not seen one while hunting in the wild in my lifetime.\n\nWe can make many things with their mandibles, from spearheads to electrified traps. I will put this to good use.", objectives = "Show the Crackling Mandible to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56455] = { id = 56455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzy Fang", description = "<You remove a fully-grown fang from the fallen frenzy.\n\nYou have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find use for this?>", completion = "<Itanu holds the tooth between his fingers.>\n\nThe frenzies serve none but themselves.\n\nYou do not know of them.\n\n<Itanu looks at the open sky.>\n\nThey cannot come here, now. Once they were a force that even the naga feared. Even their most powerful champions feared them.\n\nWhat little light we would have would be doused, when the frenzies would come. Their numbers would blot out the sun. Their teeth would find all unhidden flesh.\n\nYou will never know the terror of the deeps, dry one.", objectives = "Show the Frenzy Fang to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56456] = { id = 56456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opaline Conch", description = "<The conch slumps following your assault -- the battle appears to be over.\n\nIt doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack.\n\nIt appears to be dead, but intact. You consider bringing the entire conch back to your allies in Mezzamere.>", completion = "Ah, a great find.\n\n<Itanu takes the conch from you and flips it over. Before you can see it, he has a small knife in hand. The conch is quickly speared, the slug within removed.>\n\nMost delightful! It would ruin it to touch fire. This... is a delicacy. It must be savored.\n\n<Itanu closes his eyes and breathes deeply, then devours the snail in a single gulp.>\n\nHm, mm. Slimy, oddly rough on the insides. \n\nMagnificent.", objectives = "Show the Opaline Conch to Artisan Itanu in Mezzamere in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56457] = { id = 56457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leathery Venom Gland", description = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind.\n\nThis toxin appears to be very potent. It would be best to bring it back to Newhome.>", completion = "Is that a venom gland in your pocket or... why is that in your pocket? You know how potent those things are, right?\n\nYeah, the snapdragons have been a pain in our side for a long time. The naga can easily sway them with their mind-bending tricks, or even just meat, they're not very smart creatures. A few good meals and they're as good as tamed.\n\nI've heard of a naga commander that can handle the venom in combat. Rumor has it she even eats the stuff. \n\nHope I never meet her!", objectives = "Show the Leathery Venom Gland to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56458] = { id = 56458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opaline Conch", description = "<The conch slumps following your assault -- the battle appears to be over.\n\nIt doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack.\n\nIt appears to be dead, but intact. You consider bringing the entire conch back to your allies in Newhome.>", completion = "Oh, hey, that's a giant conch, right? Let me see that.\n\n<Palta flips the conch over and pulls the innards out by the antennae.>\n\nThat's the stuff. Look at it! Full-slime, all scales, this one is going to be great.\n\nI'll prepare this for the meal tonight, that should lift some spirits. Nothing like a slice of spireshell to remind you of home.\n\nThanks for bringing this.\n\n<Palta nods at you.>", objectives = "Show the Opaline Conch to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56459] = { id = 56459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Digested Deepcoral Pod", description = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods.\n\nYou've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays.\n\nThis may explain their strange ability to fly.\n\nFinder Palta might know more.>", completion = "Hey, you're back! What's that? Something you ate?\n\nOh, yeah, the fathom rays love these pods. They grow on the coral around the area, seem to be filled with gas.\n\nI always thought it was just air but it appears it's lighter than air, I can fill a fishskin with what's in a pod and it floats above water!\n\nMust help them survive in the deeps, somehow. Not sure how that works, life is a mystery, you know?", objectives = "Show the Half-Digested Deepcoral Pod to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56460] = { id = 56460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Molted Spineshell", description = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar.\n\nThe spines that stick out from it are quite sharp.\n\nFinder Palta may have some use for this.>", completion = "A spine crab shell? We find them around, though I try to stay away from the dark places myself.\n\nThat's where they live, you see? The spine crabs lurk in the darkness, waiting for fish to spear. Once I saw a group of them skewer a whale shark! \n\nWhen they devour prey, they make a chittering noise -- I hate it.\n\nThe shells themselves aren't very useful -- they get brittle and shatter easily.\n\nWatch!\n\n<Palta flings the shell against a nearby rock, shattering it to pieces.>\n\nWoo-ha!", objectives = "Show the Molted Spineshell to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56461] = { id = 56461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearlescent Shell", description = "<A large, hardened shell of a vanquished hermit crab.\n\nThe shell itself was much larger than the crab, and shines in different colors when you look at it at different angles.\n\nSurely someone back at Newhome would be interested in this beautiful shell.>", completion = "That's a big shell! Like the sheen on it, too. Really catches the light, especially now that we can see the sun directly.\n\nYou know what I haven't made in a while? With all this fighting and barely surviving? Jewelry. I miss it! We used to find all kinds of things to wear dropped by your ships.\n\n<Palta smashes the shell into many pieces and holds two irregular shards up to her ears.>\n\nWell, how do I look?\n\n<Do you answer?>", objectives = "Show the Pearlescent Shell to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56462] = { id = 56462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eel Jelly", description = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime.\n\nThe slime coats your hands and arms, and seems quite difficult to remove.\n\nOne of your deep sea allies may know more about it.>", completion = "You are really covered in slime, there. Mind if I take some?\n\nEel jelly is incredibly useful to us. Not a whole lot of things can be used to make things slippery underwater, you know. Eel jelly is just great at it.\n\nHere, let me show you.\n\n<Palta rubs some jelly on your arms and legs.>\n\nYour skin is looking better already! Slimier. Much better.", objectives = "Show the Eel Jelly to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56463] = { id = 56463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mottled Hydra Scale", description = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors.\n\nThere appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", completion = "You'd like to know a little about the hydra of the area? Not much to tell, truth be told.\n\nThere are three matriarchs, they've been battling for dominance of the area for generations.\n\nSometimes, the naga throw slaves to them, for their amusement.\n\nThey don't serve anyone, just themselves. The depths aren't aligned against you, newcomer. They're just... hostile to outsiders.", objectives = "Show the Mottled Hydra Scale to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56464] = { id = 56464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Organ", description = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb.\n\nThe octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them.\n\nSomeone in Newhome may know more.>", completion = "Mindbender brain-organ? Great, thanks, I have a use for this.\n\nThey use this organ to attack our thoughts. Or, at least, it's a part of the process.\n\nHere, watch.\n\n<Palta points the organ at you and pokes it. You hear a deafening psychic scream in your mind.>\n\nIt's like they were made just to service the Old Gods and drive people insane.\n\nAnyway, thanks. I'm going to save this for when my friend comes over to talk about her gardening.", objectives = "Show the Strange Organ to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56465] = { id = 56465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overgrown Stone", description = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants.\n\nYou have not seen many such creatures in the deeps. Perhaps there is a story to them.\n\nOne of your new undersea allies may know more.>", completion = "Hey, what's that? Really fuzzy rock you've got there.\n\nIt's from one of those earthy elementals? Oh, neat, yeah I can use that. Things grow on them like crazy, I just need to plant it in the garden and the next crop will be great.\n\nNot sure where the elementals came from. We don't see many of them around, they're quite rare.\n\nAnyway, thanks! Think I'm going to make my own kelp garden with this one.", objectives = "Show the Overgrown Stone to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56466] = { id = 56466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crackling Mandible", description = "<The mandible of a tidal guardian, still crackling with electricity.\n\nOne of your new allies might have a use for this.>", completion = "Yowch! You've got to warn a person before you hand them something electric! You picked this up from a tidal guardian?\n\nThe tidal guardians have guarded the naga domain for as long as I can remember. It seems like they have always been intertwined, I can't recall ever having seen one in the wild.\n\nThey're really quite beautiful when they're swimming, mesmerizing even.\n\nAnyway, I use these things to make drinks. You mix some kelpflower wine with a bit of ground mandible, really gives it a kick!", objectives = "Show the Crackling Mandible to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56467] = { id = 56467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzy Fang", description = "<You remove a fully-grown fang from the fallen frenzy.\n\nYou have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find a use for this?>", completion = "<Palta pokes the tip of the fang.>\n\nFrenzy fang, huh? Those things... we don't joke about them.\n\n<Palta looks up at the open air.>\n\nYou're lucky, they can't come here anymore.\n\nI remember, one time, we had gone out looking for supplies. I was the only one to make it back. I can still hear the screams of the devoured. They came out of nowhere, by the hundreds. It was all clouds of red.\n\nThe deep places of the world are dangerous, friend. Avoid them if you can.", objectives = "Show the Frenzy Fang to Finder Palta in Newhome in Nazjatar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56469] = { id = 56469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirates? I Hate Those Guys!", description = "<An old pirate hat. Seems out of place on this island, perhaps Reno Jackson will know what to make of it>", completion = "I suspected pirate activity here! All these strange items we're finding are their plundered loot.", objectives = "Deliver the old pirate hat to Reno Jackson.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56470] = { id = 56470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give A Dog A Bone", description = "Louison lent me Dog Bone to help uncover some marrowgrubs, but I'm busy here with the stoves. Could you be a dear and go hunting for me?\n\nDog Bone loves to pounce on the smaller nibblers and makes a lot of noise doing it. That'll scare the larger marrowgrubs into making a run for it. That's when you'll need to make your move.\n\nJust use this bone to lure Dog Bone near the nibblers. Oh, and don't forget to harvest the flesh from the marrowgrubs! That's what you're really after.", progress = "Did you collect the meat?", completion = "Wonderful! This will make something tasty!", objectives = "Collect 12 Marrowgrub Flesh from Giant Marrowgrubs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56471] = { id = 56471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unprofitable Ventures", description = "This land is already a monumental disaster, but it could get worse!\n\nThe Venture Company is here, and will exploit this land for every ounce of profit they can make. We must make their venture here unprofitable, so they will leave.\n\nDestroy the three expensive security units with them, and they may leave for more profitable ventures.", completion = "This certainly hurts their profits. Now we see if they leave!", objectives = "Destroy Pummeller Red, Pummeller Orange, and Pummeller Grey", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56472] = { id = 56472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Uldum Accord", description = "You seek assistance defending the Forge of Origination? It would seem that our goals align.\n\nThe Halls of Origination are but a small portion of the forge's true scope. Any threat to Uldum would be a potential threat to the forge, and Uldum has found itself with many new enemies of late.\n\nWe were about to convene the High Council when these Wastewanders arrived unannounced. Perhaps you could join us in learning about these threats?", progress = "We should learn all we can about the threats facing Uldum before we proceed.", completion = "Our accord with the Wastewanders and the Explorer's League will aid us in defending Uldum. \n\nYet even with our combined strength, we may not be able to hold these enemies at bay without your help.", objectives = "Learn about the threats facing Uldum in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56473] = { id = 56473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envenomed Spider Fang", description = "Even wary bees have been known to fall prey to these enormous spiders. They lie in wait near flowerbeds and ambush them while they collect their harvest. Thanks to you, they have one less spider to worry about.\n\nThe Hivemother will be interested in this item.", completion = "<The Hivemother buzzes at you.>\n\nBzzzzzz!", objectives = "Take the Envenomed Spider Fang to the Honeyback Hivemother for a reward.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
